def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def advance():
        nonlocal pos
        pos += 1

    def trunc_div(a, b):
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while True:
            typ, _ = peek()
            if typ == '+':
                advance()
                val = val + parse_term()
            elif typ == '-':
                advance()
                val = val - parse_term()
            else:
                break
        return val

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while True:
            typ, _ = peek()
            if typ == '*':
                advance()
                val = val * parse_factor()
            elif typ == '/':
                advance()
                rhs = parse_factor()
                val = trunc_div(val, rhs)
            else:
                break
        return val

    def parse_factor():
        nonlocal pos
        typ, _ = peek()
        if typ == '-':
            advance()
            return -parse_factor()
        if typ == '+':
            advance()
            return parse_factor()
        return parse_primary()

    def parse_primary():
        nonlocal pos
        typ, val = peek()
        if typ == 'NUM':
            advance()
            return val
        if typ == '(':
            advance()
            v = parse_expr()
            typ2, _ = peek()
            if typ2 != ')':
                raise ValueError("Expected ')'")
            advance()
            return v
        raise ValueError(f"Unexpected token: {typ}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

